function classification = classifyDiffusionNature( ...
        freeModel, trapModel, hopComparison, stickyBnp, opts)
%CLASSIFYDIFFUSIONNATURE Combine independent trap and hop evidence channels.

    deltaTrap = NaN;
    if freeModel.estimateAvailable && trapModel.estimateAvailable
        deltaTrap = freeModel.bic - trapModel.bic;
    end
    deltaHop = hopComparison.deltaHopQuasiBic;
    usableHopRadiusUm = min(opts.maxLocalizationRadiusUm, ...
        opts.laserWaistUm);

    trapStrong = isfinite(deltaTrap) && ...
        deltaTrap >= opts.bicEvidenceThreshold && ...
        trapModel.diffusionRatioSlowToFast <= ...
        opts.maximumTrapDiffusionRatio && ...
        min(trapModel.stateOccupancy) >= ...
        opts.minimumTrapStateOccupancyFraction;
    hopStrong = isfinite(deltaHop) && ...
        deltaHop >= opts.bicEvidenceThreshold && ...
        hopComparison.shortToLongDiffusionRatio >= ...
        opts.minimumHopDiffusionRatio && ...
        hopComparison.effectiveCompartmentSizeUm <= ...
        opts.maximumCompartmentFractionOfLocalizationRadius * ...
        usableHopRadiusUm;

    if trapStrong && hopStrong
        label = 'mixed hop and trap';
    elseif trapStrong
        label = 'trap diffusion';
    elseif hopStrong
        label = 'hop diffusion';
    elseif isfinite(deltaTrap) || isfinite(deltaHop)
        label = 'free or unresolved';
    else
        label = 'insufficient data';
    end

    classification = struct();
    classification.label = label;
    classification.deltaTrapBic = deltaTrap;
    classification.deltaHopQuasiBic = deltaHop;
    classification.trapEvidenceStrong = trapStrong;
    classification.hopEvidenceStrong = hopStrong;
    classification.evidenceThreshold = opts.bicEvidenceThreshold;
    classification.maximumTrapDiffusionRatio = ...
        opts.maximumTrapDiffusionRatio;
    classification.minimumTrapStateOccupancyFraction = ...
        opts.minimumTrapStateOccupancyFraction;
    classification.minimumHopDiffusionRatio = ...
        opts.minimumHopDiffusionRatio;
    classification.maximumCompartmentFractionOfLocalizationRadius = ...
        opts.maximumCompartmentFractionOfLocalizationRadius;
    classification.usableHopRadiusUm = usableHopRadiusUm;
    classification.hopLengthScaleInsideUsableField = ...
        hopComparison.effectiveCompartmentSizeUm <= ...
        opts.maximumCompartmentFractionOfLocalizationRadius * ...
        usableHopRadiusUm;
    classification.bnpPosteriorModeStateCount = NaN;
    if stickyBnp.estimateAvailable
        classification.bnpPosteriorModeStateCount = ...
            stickyBnp.posteriorModeStateCount;
    end
    classification.interpretation = [ ...
        'Trap and hop score differences use different likelihoods. ' ...
        'Threshold each difference separately; do not compare their ' ...
        'absolute BIC values.'];
end
